+import type {TotalUsageMetadata} from '../index.js';
+
+// specs/hal-engine-config-hooks/spec.md#11
+it('exposes the hook usage as a deliberately named whole-turn total', () => {
+  const total: TotalUsageMetadata = {inputTokens: 8, outputTokens: 5, totalTokens: 13};
+  const hook: NonNullable<OrchestratorHooks['afterModelResponse']> = async (_session, _text, totalUsage) => {
+    const received: TotalUsageMetadata | undefined = totalUsage;
+    expect(received).toBe(total);
+  };
+
+  expect({hook, scope: TOTAL_USAGE_SCOPE}).toEqual({hook: expect.any(Function), scope: 'turn'});
+});
